mapper.sql:
LEFT JOIN t_sr_strategy_period_summary_ap s
    ON s.strategy_id = f.strategy_id
   AND s.tab_type = f.tab_type
   AND s.channel = f.channel
   AND DATE_FORMAT(s.stat_month, '%Y-%m') = #{statMonth}
   AND s.is_deleted = 0
   AND s.city_id = #{query.cityId}
   AND s.county_id = #{query.countyId}
LEFT JOIN t_sr_dim_channel d ON d.key_code = f.channel

LEFT JOIN t_sr_strategy_period_summary_ctrl s
    ON s.strategy_id = f.strategy_id
   AND s.channel = f.channel
   AND DATE_FORMAT(s.stat_month, '%Y-%m') = #{statMonth}
   AND s.is_deleted = 0
   AND s.city_id = #{query.cityId}
   AND s.county_id = #{query.countyId}
LEFT JOIN t_sr_dim_channel d ON d.key_code = f.channel

choose.when:
SELECT f.id AS id, f.strategy_id AS strategyId, f.strategy_name AS strategyName, COALESCE(s.strategy_code, f.strategy_id) AS strategyCode, s.big_category AS bigCategory, s.small_category AS smallCategory, f.channel AS channel, d.key_name AS channelName, DATE_FORMAT(f.create_time, '%Y-%m-%d %H:%i') AS favTime, f.source AS source, s.consult_count AS consultCount, s.consult_count_qoq AS consultCountQoQ, s.retain_count AS retainCount, s.retain_count_qoq AS retainCountQoQ, s.retain_rate AS retainRate, s.retain_rate_qoq AS retainRateQoQ, s.dispatch_count AS dispatchCount, s.dispatch_count_qoq AS dispatchCountQoQ, s.success_count AS successCount, s.success_count_qoq AS successCountQoQ, s.success_rate AS successRate, s.success_rate_qoq AS successRateQoQ, s.income AS income, s.income_qoq AS incomeQoQ, DATE_FORMAT(s.stat_month, '%Y-%m-%d') AS statMonth FROM t_sr_favorite f
WHERE f.user_id = #{userId} AND f.tab_type = #{tabType} AND f.is_deleted = 0
ORDER BY f.create_time DESC LIMIT #{limit} OFFSET #{offset}

choose.otherwise:
SELECT f.id AS id, f.strategy_id AS strategyId, f.strategy_name AS strategyName, s.big_category AS bigCategory, s.small_category AS smallCategory, s.strategy_class AS strategyClass, f.channel AS channel, d.key_name AS channelName, DATE_FORMAT(f.create_time, '%Y-%m-%d %H:%i') AS favTime, f.source AS source, s.original_cust AS originalCust, s.original_cust_qoq AS originalCustQoQ, s.push_count AS pushCount, s.push_count_qoq AS pushCountQoQ, s.usage_count AS usageCount, s.usage_count_qoq AS usageCountQoQ, s.usage_rate AS usageRate, s.usage_rate_qoq AS usageRateQoQ, s.reach_count AS reachCount, s.reach_count_qoq AS reachCountQoQ, s.target_conv_num AS targetConvNum, s.target_conv_num_qoq AS targetConvNumQoQ, s.target_conv_rate AS targetConvRate, s.target_conv_rate_qoq AS targetConvRateQoQ, s.product_conv_num AS productConvNum, s.product_conv_num_qoq AS productConvNumQoQ, s.product_conv_rate AS productConvRate, s.product_conv_rate_qoq AS productConvRateQoQ, s.expected_income AS expectedIncome, s.expected_income_qoq AS expectedIncomeQoQ, s.actual_income AS actualIncome, s.actual_income_qoq AS actualIncomeQoQ, DATE_FORMAT(s.stat_month, '%Y-%m-%d') AS statMonth FROM t_sr_favorite f
WHERE f.user_id = #{userId} AND f.tab_type = #{tabType} AND f.is_deleted = 0
ORDER BY f.create_time DESC LIMIT #{limit} OFFSET #{offset}

mapper.select:
SELECT COUNT(1)
FROM t_sr_favorite f
WHERE f.user_id = #{userId}
  AND f.tab_type = #{tabType}
  AND f.is_deleted = 0

SELECT f.strategy_id AS strategyId,
       f.source AS source,
       f.rule_id AS ruleId
FROM t_sr_favorite f
WHERE f.user_id = #{userId}
  AND f.tab_type = #{tabType}
  AND f.is_deleted = 0
  AND f.strategy_id IN

    #{sid}

FOR UPDATE

mapper.update:
UPDATE t_sr_favorite
SET source = #{source}, rule_id = #{ruleId}, update_time = NOW()
WHERE user_id = #{userId}
  AND tab_type = #{tabType}
  AND strategy_id = #{strategyId}
  AND is_deleted = 0

mapper.select:
SELECT f.strategy_id
FROM t_sr_favorite f
WHERE f.user_id = #{userId}
  AND f.tab_type = #{tabType}
  AND f.is_deleted = 0
  AND f.strategy_id IN

    #{sid}

mapper.delete:
DELETE FROM t_sr_favorite
WHERE user_id = #{userId}
  AND tab_type = #{tabType}
  AND strategy_id = #{strategyId}

mapper.update:
UPDATE t_sr_favorite
SET is_deleted = 1, update_time = NOW()
WHERE user_id = #{userId}
  AND tab_type = #{tabType}
  AND is_deleted = 0
  AND strategy_id IN

    #{sid}

mapper.select:
SELECT s.strategy_id AS strategyId, MAX(s.strategy_name) AS strategyName, MIN(s.channel) AS channel FROM t_sr_strategy_period_summary_ap s WHERE s.tab_type = #{tabType} AND s.is_deleted = 0 AND s.strategy_id IN
#{sid}
GROUP BY s.strategy_id

SELECT s.strategy_id AS strategyId, MAX(s.strategy_name) AS strategyName, MIN(s.channel) AS channel FROM t_sr_strategy_period_summary_ctrl s WHERE s.is_deleted = 0 AND s.strategy_id IN
#{sid}
GROUP BY s.strategy_id
